// calcule e mostre os três valores aqui

exercises.solution:
const quiloDoQueijo = 4590;
const pesoDoQueijo = 0.735;
const quiloDoPresunto = 3990;
const pesoDoPresunto = 0.25;

const queijo = Math.round(quiloDoQueijo * pesoDoQueijo);
const presunto = Math.round(quiloDoPresunto * pesoDoPresunto);
const total = queijo + presunto;

console.log('Queijo:', queijo, 'centavos');
console.log('Presunto:', presunto, 'centavos');
console.log('Total:', total, 'centavos');

