exercises.solution:
const mensalidade = 89.9;
const percentual = 15;

const mensalidadeCentavos = Math.round(mensalidade * 100);
const descontoCentavos = Math.round(mensalidadeCentavos * percentual / 100);
const aPagarCentavos = mensalidadeCentavos - descontoCentavos;

console.log('Mensalidade:', mensalidadeCentavos, 'centavos');
console.log('Desconto:', descontoCentavos, 'centavos');
console.log('A pagar: R$', (aPagarCentavos / 100).toFixed(2));

